// sourceName says where the device came from.
func sourceName(src string) string {
	switch src {
	case "manual":
		return "Added by hand"
	case "scan":
		return "Found by a scan"
	case "proxmox":
		return "Proxmox"
	case "wireguard":
		return "WireGuard"
	case "pihole":
		return "Pi-hole"
	case "adguard":
		return "AdGuard Home"
	case "opnsense":
		return "OPNsense"
	case "":
		return "Unknown"
	}
	return src
}

